    },
    {
      "offset": 4,
      "meaning": "conn_env 32-bit value copied into the event buffer"
    },
    {
      "offset": 8,
      "meaning": "conn_env 16-bit value copied into the event buffer (possibly handle-like field)"
    },
    {
      "offset": 10,
      "meaning": "conn_env byte flag selecting the extra-event path when the pending list has one entry"
    },
    {
      "offset": 11,
